"""Static local review of the four-priority candidate, with no external assets."""
import json


def markdown_report(board):
    lines = ["# Primacy → Efficiency → Substance → Volume", "",
             "Corrected isolated candidate. Production rankings and the earlier three-factor run are unchanged.", "",
             f"Frozen evidence cutoff: {board['as_of']}. Baseline: **{board['baseline']['status']}**.", "",
             "Ranking follows the stated priorities in order, with no scalar blend. Efficiency is progressive five-stage credit normalized within each historical chamber. Substance is the average impact class of beneficial engagements. Volume counts beneficial engagement after role and joining-time adjustments, without impact weighting. Missing higher-priority evidence prevents lower criteria from improving that member's position.", "",
             "Institutional position has no tier-scoring field or multiplier. Real legislative milestones still count. Existing evidence, conduct, override and fixed-seat rules are applied after the analytical ordering.", "",
             "**Substance limitation:** selected bills currently have provisional weight 5. Equal average substance is a tie, not a finding that every bill is equally important. The publication evidence does not yet support significance upgrades. The 180-day cosponsor half-life is the existing illustrative setting, not a validated optimum.", ""]
    for term in board["terms"].values():
        s = term["summary"]
        lines += [f"## Congress {term['congress']}", "",
                  f"{s['members']} displayed members; {s['efficiency_observed']} with available progressive efficiency, {s['substance_observed']} with a provisional or reviewed substance mean. Candidate tiers available: **{term['candidate_tiers_available']}**.", "",
                  f"Changed ranks: **{s['rank_changes']}**. Changed tier memberships: **{s['tier_changes']}**.", "",
                  "| Member | P | E percentile | Progressive E | Mean substance | Weighted volume | Beneficial measures | Legacy rank/tier | Candidate rank/tier |",
                  "|---|---:|---:|---:|---:|---:|---:|---:|---:|"]
        def num(v):
            return "unavailable" if v is None else f"{v:.6f}"
        for row in term["members"][:20]:
            name = row["name"].replace("|", "\\|").replace("\n", " ")
            lines.append(f"| {name} | {num(row['P'])} | {num(row['efficiency_score'])} | {num(row['efficiency_raw'])} | {num(row['substance_raw'])} | {num(row['volume_raw'])} | {row['useful_volume']} | {row['legacy_rank']}/{row['legacy_tier']} | {row['candidate_rank']}/{row['candidate_tier']} |")
        lines += ["", "Full roster, per-member coverage and stage breakdowns are in board.json. Every selected engagement is traced in contributions.ndjson.", "",
                  "### Denominator and coverage receipts", "", "```json",
                  json.dumps({"chambers": term.get("chamber_terms"), "gates": term["gates"],
                              "reserved_number_exclusions": term["input_coverage"].get("reserved_number_exclusions", []),
                              "impact_weights": term["input_coverage"].get("selected_impact_weights")}, indent=2),
                  "```", ""]
        if term["gate_errors"]:
            lines += ["Candidate publication withheld:", "", "```json", json.dumps(term["gate_errors"], indent=2), "```", ""]
    lines += ["## Interpretation", "",
              "The priority order is strict: efficiency, substance and volume only resolve ties in preceding criteria. A stronger lower-priority score cannot compensate for lower primacy. Changes in those tie-breakers need not change the highest tiers.", "",
              "118th and 119th Congress are separate retrospective comparisons using the current published primacy board. They are not out-of-sample validation or estimates of individual causal impact. Unverified letter dates remain coverage records, with no invented legislative stages.", ""]
    return "\n".join(lines)


def review_html(board):
    payload = json.dumps(board, ensure_ascii=False, allow_nan=False).replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    return """<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Primacy, Efficiency, Substance, Volume</title><style>
:root{font-family:Segoe UI,Arial,sans-serif;color:#183248;background:#f2f5f7}*{box-sizing:border-box}body{margin:0}header{padding:30px max(24px,4vw);background:#153549;color:#fff}.eyebrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#a5d6d3}h1{font-size:clamp(23px,3vw,35px);font-weight:600;margin:13px 0}header p{max-width:1020px;color:#d5e4ed;line-height:1.55}main{padding:24px max(24px,4vw)}.note{background:#fff8df;border-left:4px solid #ba9137;padding:13px 17px;line-height:1.5;margin-bottom:16px}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0}input,select{font:inherit;padding:10px 12px;border:1px solid #bbcbd7;border-radius:5px;background:#fff}input{flex:1;min-width:230px}.cards{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));gap:12px}.card{background:#fff;padding:18px;border:1px solid #d8e1e7;border-radius:6px}.card strong{display:block;font-size:28px;margin-bottom:5px}.muted{color:#546c7d;font-size:13px;line-height:1.6}.table{overflow:auto;border:1px solid #d8e1e7;border-radius:6px;background:#fff}table{border-collapse:collapse;width:100%;white-space:nowrap;font-size:13px}th,td{text-align:right;padding:12px 10px;border-bottom:1px solid #e4ebef}th{background:#e6eef3;position:sticky;top:0}td:nth-child(2),th:nth-child(2){text-align:left}tbody tr:hover{background:#f0f8f8}.member{background:none;border:0;padding:0;color:#056f79;font:inherit;text-align:left;text-decoration:underline;cursor:pointer}.changed{background:#fff0cf}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.metric{padding:15px;border:1px solid #d8e1e7;background:#fff}.metric strong{display:block;font-size:22px;margin-bottom:5px}details{margin:20px 0}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;background:#e9f0f4;padding:16px}a{color:#006e7e}#member-panel{margin-top:24px;background:#fff;border:1px solid #c3d3dd;border-radius:6px;padding:22px}#member-panel h2{margin-top:0}#member-panel button.close{float:right;border:1px solid #b4c7d4;background:#fff;border-radius:4px;padding:6px 10px;cursor:pointer}.pill{display:inline-block;font-size:11px;color:#7b5f17;background:#fff4ce;padding:2px 6px;border-radius:3px;margin-left:5px}footer{margin:25px 0;font-size:13px}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #00a5aa;outline-offset:3px}@media(max-width:700px){.cards,.metrics{grid-template-columns:repeat(2,1fr)}header,main{padding:20px}h1{line-height:1.3}}
</style><header><div class="eyebrow">Legislative effectiveness · corrected candidate</div><h1>Primacy → Efficiency → Substance → Volume</h1><p>Four priorities, compared in order. Progressive legislative results, distinct substance and volume measures, and less credit for joining late.</p></header>
<main><div id="notice" class="note"></div><div class="note"><strong>Substance is provisional.</strong> All selected measures currently carry weight 5. Their equal substance scores provide no ranking distinction; a low percentile here does not mean poor substantive work.</div>
<div class="controls"><select id="term" aria-label="Congress"></select><select id="chamber" aria-label="Chamber"><option value="">Both chambers</option value="house">House</option><option value="senate">Senate</option></select><select id="tier" aria-label="Candidate tier"><option value="">All tiers</option><option value="1">Tier 1</option><option value="2">Tier 2</option><option value="3">Tier 3</option><option value="0">Outside tiers</option></select><input id="search" placeholder="Search members" aria-label="Search members"></div>
<div class="cards" id="cards"></div><p class="muted" id="count"></p>
<div class="table"><table><thead><tr><th>Candidate rank</th><th>Member / chamber</th><th>P</th><th>E percentile</th><th>Mean substance</th><th>Weighted volume</th><th>Beneficial measures</th><th>Legacy rank / tier</th><th>Candidate tier</th><th>Rank change</th></tr></thead><tbody id="rows"></tbody></table></div>
<p class="muted">Select a member for raw results, five-stage credit and coverage. Later priorities only break ties in earlier ones. Missing higher-priority evidence blocks lower-priority tie-breakers. Evidence and conduct rules still govern final seats.</p>
<section id="member-panel" hidden aria-live="polite"><button class="close" id="close-member">Close</button><h2 id="member-name"></h2><div class="metrics" id="member-metrics"></div><p id="member-status" class="muted"></p><details open><summary>Five-stage results and role attribution</summary><pre id="member-stages"></pre></details><details><summary>Coverage and policy adjustments</summary><pre id="member-coverage"></pre></details></section>
<details><summary>How the four criteria work</summary><p><strong>Primacy:</strong> the published beneficiary-orientation factor. <strong>Efficiency:</strong> five additive chamber-normalized stage shares, with impact, CU direction, role and joining-time credit. <strong>Substance:</strong> average impact weight per beneficial engagement. <strong>Volume:</strong> distinct beneficial engagements weighted by CU relevance, role and joining time, without an impact multiplier.</p><p>Later cosponsors retain their base role weight and receive a discount of 2 raised to minus their joining delay divided by 180 days. Joining must be verified against service history; milestone credit follows the active official sponsorship, without an extra service-exit discount. The 180-day half-life is a candidate setting. Institutional position adds no tier points; achieved milestones count.</p><p>Five stages: introduction, committee action, action beyond committee, passage in the originating chamber, and enactment. Unverified letter dates remain outside this lawmaking measure.</p></details>
<details><summary>Evidence, denominators and audit gates</summary><pre id="audit"></pre></details>
<footer><a href="board.json">Full board data</a> · <a href="contributions.ndjson">Contribution ledger</a> · <a href="receipt.json">Run receipt</a> · <a href="report.md">Report</a></footer></main>
<script id="data" type="application/json">""" + payload + """</script><script>
const data=JSON.parse(document.getElementById('data').textContent),term=document.getElementById('term'),search=document.getElementById('search'),chamber=document.getElementById('chamber'),tier=document.getElementById('tier');
Object.keys(data.terms).forEach(k=>{const o=document.createElement('option');o.value=k;o.textContent='Congress '+k;term.append(o)});term.value=String(data.default_congress);
const fmt=(v,p=5)=>v==null?'Unavailable':Number(v).toFixed(p),pct=v=>v==null?'Unavailable':(v*100).toFixed(1)+'%',human=v=>(v||'Unavailable').replaceAll('_',' ');
function showMember(r){document.getElementById('member-panel').hidden=false;document.getElementById('member-name').textContent=r.name+' · '+r.term_chamber;const m=document.getElementById('member-metrics');m.replaceChildren();[['Primacy',fmt(r.P,6)],['Progressive efficiency',fmt(r.efficiency_raw,6)],['Mean substance',fmt(r.substance_raw,2)],['Weighted volume',fmt(r.volume_raw,3)]].forEach(([label,value])=>{const e=document.createElement('div');e.className='metric';const v=document.createElement('strong');v.textContent=value;e.append(v,document.createTextNode(label));m.append(e)});document.getElementById('member-status').textContent='Efficiency: '+human(r.efficiency_status)+' · Substance: '+human(r.substance_status)+' · Volume: '+human(r.volume_status);document.getElementById('member-stages').textContent=JSON.stringify({stages:r.stages,roles:r.roles},null,2);document.getElementById('member-coverage').textContent=JSON.stringify({coverage:r.coverage,conduct:r.conduct,strict_rank:r.strict_rank,candidate_rank:r.candidate_rank,positive_measures:r.useful_volume,harmful_measures:r.harmful_volume,unknown_measures:r.unknown_volume},null,2);document.getElementById('member-panel').scrollIntoView({behavior:'smooth',block:'nearest'})}
function draw(){const t=data.terms[term.value],q=search.value.toLowerCase(),rows=t.members.filter(r=>r.name.toLowerCase().includes(q)&&(!chamber.value||r.term_chamber===chamber.value)&&(!tier.value||String(r.candidate_tier)===tier.value));document.getElementById('member-panel').hidden=true;document.getElementById('notice').textContent=t.candidate_tiers_available?'Completed candidate comparison. Production is unchanged. The original published board reproduces exactly.':'Candidate tier assignments withheld: a baseline or audit gate failed. Analytical metrics remain available for inspection.';
const cards=document.getElementById('cards');cards.replaceChildren();[['Members',t.summary.members],['Available efficiency',t.summary.efficiency_observed],['Changed tier memberships',t.summary.tier_changes??'Withheld'],['Changed ranks',t.summary.rank_changes??'Withheld']].forEach(([label,value])=>{const e=document.createElement('div');e.className='card';const v=document.createElement('strong');v.textContent=value;e.append(v,document.createTextNode(label));cards.append(e)});document.getElementById('count').textContent=rows.length+' members shown · evidence cutoff '+t.as_of+' · separate Congress comparisons';const tbody=document.getElementById('rows');tbody.replaceChildren();rows.forEach(r=>{const tr=document.createElement('tr'),delta=r.candidate_rank==null||r.legacy_rank==null?null:r.legacy_rank-r.candidate_rank;[r.candidate_rank??'—',r.name+' / '+r.term_chamber,fmt(r.P,6),pct(r.efficiency_score),fmt(r.substance_raw,2),fmt(r.volume_raw,3),r.useful_volume,(r.legacy_rank??'—')+' / '+(r.legacy_tier??'—'),r.candidate_tier??'—',delta==null?'—':delta===0?'—':delta>0?'↑ '+delta:'↓ '+(-delta)].forEach((value,i)=>{const td=document.createElement('td');td.textContent=value;if(i===1){td.replaceChildren();const b=document.createElement('button');b.className='member';b.textContent=value;b.addEventListener('click',()=>showMember(r));td.append(b)}if(i===8&&r.candidate_tier!=null&&r.candidate_tier!==r.legacy_tier)td.className='changed';tr.append(td)});tbody.append(tr)});document.getElementById('audit').textContent=JSON.stringify({baseline:data.baseline,policy:t.policy,gates:t.gates,errors:t.gate_errors,chambers:t.chamber_terms,coverage:t.input_coverage},null,2)}
[term,chamber,tier].forEach(e=>e.addEventListener('change',draw));search.addEventListener('input',draw);document.getElementById('close-member').addEventListener('click',()=>document.getElementById('member-panel').hidden=true);draw();
</script></html>"""
